CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, username VARCHAR(60) NOT NULL UNIQUE, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('superadmin','staff') NOT NULL DEFAULT 'staff', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE content (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, type VARCHAR(30) NOT NULL, title VARCHAR(190) NOT NULL, slug VARCHAR(190) NOT NULL UNIQUE, excerpt TEXT NULL, body LONGTEXT NULL, image_path VARCHAR(255) NULL, status ENUM('draft','published') NOT NULL DEFAULT 'draft', meta_title VARCHAR(190) NULL, meta_description VARCHAR(255) NULL, published_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(type,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE inquiries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, bride_name VARCHAR(100) NOT NULL, groom_name VARCHAR(100) NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(40) NOT NULL, wedding_date DATE NULL, venue VARCHAR(190) NULL, guests SMALLINT UNSIGNED NULL, decoration_style VARCHAR(100) NULL, flower_preference VARCHAR(190) NULL, budget VARCHAR(100) NULL, contact_method VARCHAR(30) NULL, notes TEXT NULL, inspiration_path VARCHAR(255) NULL, status ENUM('new','contacted','closed') DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE contact_messages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(40) NULL, subject VARCHAR(190) NOT NULL, message TEXT NOT NULL, status ENUM('new','replied','closed') DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings (`key` VARCHAR(100) PRIMARY KEY, `value` TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- Create accounts after import: run php scripts/create_admin.php once, then delete it.
